SELECT t.id, t.titulo, (SELECT json_agg(json_build_object('nome', a.nome, 'conv', CASE WHEN conv.atleta_id IS NOT NULL THEN true ELSE false END, 'pres', p.status)) FROM atletas a LEFT JOIN convocacoes conv ON conv.atleta_id = a.id AND conv.treino_id = t.id LEFT JOIN presencas p ON p.atleta_id = a.id AND p.treino_id = t.id WHERE conv.atleta_id IS NOT NULL OR p.atleta_id IS NOT NULL) as detalhes FROM treinos t WHERE t.tipo = 'JOGO' LIMIT 1;
